#!/usr/bin/env sh
# Regenerates packages/contracts/src/generated from crates/loki-core (ADR-0005).
#
#   ./scripts/gen-contracts.sh           write the generated files
#   ./scripts/gen-contracts.sh --check   regenerate into a temp dir and fail if the committed
#                                        files differ (stale contracts). CI and check.sh run this.
set -eu
cd "$(dirname "$0")/.."
root="$(pwd)"
committed="$root/packages/contracts/src/generated"

mode="${1:-write}"
case "$mode" in
  write) out="$committed" ;;
  --check) out="$(mktemp -d)/generated" ;;
  *) echo "usage: $0 [--check]" >&2; exit 2 ;;
esac

# Start from an empty directory so a type removed in Rust disappears from TypeScript too.
rm -rf "$out"
mkdir -p "$out"

# ts-rs writes one file per `#[ts(export)]` type from tests it generates. Only those tests run.
TS_RS_EXPORT_DIR="$out" cargo test -p loki-core --features ts --quiet export_bindings >/dev/null

# Barrel file, sorted with the C locale so the output is byte-identical on every OS.
{
  echo "// Generated by scripts/gen-contracts.sh. Do not edit."
  for file in $(cd "$out" && find . -name '*.ts' ! -name index.ts | sed 's#^\./##' | LC_ALL=C sort); do
    path="${file%.ts}"
    echo "export type { ${path##*/} } from \"./$path\";"
  done
} > "$out/index.ts"

if [ "$mode" = "--check" ]; then
  if diff -r "$committed" "$out"; then
    echo "Contracts are up to date."
  else
    echo "error: packages/contracts/src/generated is stale. Run ./scripts/gen-contracts.sh and commit the result." >&2
    exit 1
  fi
else
  echo "Generated $(find "$out" -name '*.ts' | wc -l | tr -d ' ') files in packages/contracts/src/generated"
fi
